import os, json, time, math
import numpy as np

RESULTS_DIR = 'storage/noesis/nmap/results'
OUT_SUMMARY = 'storage/noesis/nmap/cross_class_summary_v2_1.json'
FREEZE_DIR  = 'storage/noesis/nmap/freezes'
SNAP_C = 'storage/noesis/latest_centers.txt'
SNAP_R = 'storage/noesis/latest_radii.txt'
N = 26

K_GRID = [15, 25, 40, 60]
TOLS = [1e-9, 1e-8]
KEYS = [f'{tol}_K{K}' for tol in TOLS for K in K_GRID]

def ts():
    return time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())

def write_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w') as f:
        json.dump(obj, f, indent=2)

def load_snapshot():
    if os.path.exists(SNAP_C) and os.path.exists(SNAP_R):
        c = np.loadtxt(SNAP_C, dtype=float).reshape(N,2)
        r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
        return c, r
    # safe fallback
    centers = []
    rad = 0.08
    for i in range(5):
        for j in range(6):
            if len(centers) < N:
                centers.append([0.1+0.2*i, 0.1+0.15*j])
    return np.array(centers, float), np.full(N, rad, float)

def collect_values():
    vals = {k: [] for k in KEYS}
    idx_map_used = 0
    classes = 0
    for root, _, files in os.walk(RESULTS_DIR):
        for fn in files:
            if not fn.endswith('_compare_v2_1_refresh.json'):
                continue
            try:
                data = json.load(open(os.path.join(root, fn), 'r'))
            except Exception:
                continue
            classes += 1
            if data.get('index_map_applied'):
                idx_map_used += 1
            j = data.get('jaccards', {})
            for k in KEYS:
                v = j.get(k)
                if isinstance(v, (int, float)) and not (isinstance(v, float) and (math.isnan(v) or math.isinf(v))):
                    vals[k].append(float(v))
    return vals, classes, idx_map_used

def stats(xs):
    if not xs:
        return {'n': 0, 'mean': None, 'median': None, 'min': None, 'max': None, 'p_ge_0_5': None, 'p_ge_0_66': None}
    arr = np.array(xs, float)
    return {
        'n': int(arr.size),
        'mean': float(arr.mean()),
        'median': float(np.median(arr)),
        'min': float(arr.min()),
        'max': float(arr.max()),
        'p_ge_0_5': float((arr >= 0.5).mean()),
        'p_ge_0_66': float((arr >= 2/3).mean())
    }

def construct_packing():
    c0, r0 = load_snapshot()

    vals, classes, idx_map_used = collect_values()
    summary = {
        'generated_at': ts(),
        'classes_seen': classes,
        'index_map_applied_frac': (idx_map_used / classes) if classes else 0.0,
        'k_grid': K_GRID,
        'tols': TOLS,
        'stats': {k: stats(v) for k, v in vals.items()}
    }
    write_json(OUT_SUMMARY, summary)
    write_json(os.path.join(FREEZE_DIR, f'cross_class_summary_v2_1_{ts()}.json'), summary)

    # return baseline with tiny shrink
    r = np.maximum(r0 - 1e-9, 1e-12)
    return c0.astype(float), r.astype(float)
